 public:
  FeaturePromoRegistry();
  FeaturePromoRegistry(FeaturePromoRegistry&& other) noexcept;
  FeaturePromoRegistry& operator=(FeaturePromoRegistry&& other) noexcept;
  ~FeaturePromoRegistry() override;


