  using PageNodeVisitor = base::FunctionRef<bool(const PageNode*)>;
  using ProcessNodeVisitor = base::FunctionRef<bool(const ProcessNode*)>;
  using WorkerNodeVisitor = base::FunctionRef<bool(const WorkerNode*)>;

  Graph();

